.meta-list li:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }
.meta-label { display: block; font-size: 0.8em; font-weight: 900; text-transform: uppercase; letter-spacing: 1px; color: #a855f7; margin-bottom: 5px; }
.meta-value { display: block; font-weight: 700; color: #0f172a; }

.job-note { margin-top: 25px; background: #e0e7ff; border: 1px solid #bbf7d0; padding: 15px; border-radius: 8px; font-size: 0.85em; color: #166534; font-weight: 600; line-height: 1.5; }
.job-note strong { display: block; color: #15803d; margin-bottom: 5px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.5px; }

/* --- MAIN JOB DESCRIPTION CARD --- */
