 case 'year':
 if (value[i]) {
 $(this).datepicker('setDate', new Date(value[i]));
 }
 break;

 case 'single-select':
 let singleSelect = $('#field_' + i + '__' + IdField + '__value__select');
 let optionId = getSemanticOption(value[i], singleSelect, IdField);
 if (optionId !== '') {
 singleSelect.val(optionId);
 singleSelect.change();
 }
 break;

 case 'geoaddress':
 // values provided
 let countryCode = value[i].country_code;
 let termCap = value[i].postal_code;
 if (!termCap) {
 termCap = value[i].city;
 }
 let streetAddress = value[i].street_address;
 let houseNumber = value[i].house_number;
 let zLocationIdentifier = value[i].zlocation_identifier;

 let triggerAddress = (countryCode && countryCode !== '') && (termCap && termCap !== '');
 if (triggerAddress) {
 countryCode = countryCode.toUpperCase();
 let countrySelect = $('#autocomplete_box__selectAutocomplete_field_' + i + '__' + IdField + '__value__nazioneISO__autocompletebox');
 let countryInput = $('#field_' + i + '__' + IdField + '__value__nazioneISO__select');
 let postalcodeSelect = $('#autocomplete_box__selectAutocomplete_field_' + i + '__' + IdField + '__value__autocomplete_cap__autocompletebox');
 let postalcodeInput = $('#field_' + i + '__' + IdField + '__value__autocomplete_cap__select');
 let addressInput = $('#field_' + i + '__' + IdField + '__value__indirizzo__text');
 let housenumberInput = $('#field_' + i + '__' + IdField + '__value__civico__text');

 // Populate nationeISO
 countrySelect.val(value[i].country);
 countryInput.val(countryCode).trigger('change');

 // Dialoging with service in order to get the postalCode identifier
 $.ajax({
 type: 'POST',
 url: 'https://cezanneondemand.intervieweb.it/app.php?opmode=guest&module=CompanyAutocomplete&action=geolocation_get_postal_codes&ajax=1&back=0&CSRFToken=c08c56d54dc3ca43&CSRFHash=e622e6996e0c1b4997732fe10b654c5f5c1feba8f3567dc6dcf615cb8c0aced0',
 dataType: 'json',
 data: {
 nationId: countryCode,
 keyword: termCap
 },
 success: function (response) {
 // Populate CAP
 let postalCode = response.results.find((element) => element.value === zLocationIdentifier);
 if (undefined !== postalCode && postalCode.label && postalCode.value) {
 postalcodeSelect.val(postalCode.label);
 postalcodeInput.val(postalCode.value).trigger('change');
 }

 // Populate address and houseNumber
 addressInput.val(streetAddress).trigger('change');
 housenumberInput.val(houseNumber).trigger('change');
 },
 error: function (response) {
 console.log(response);
 }
 })
 }
 break;

 case 'image':
 if (value[i] !== '') {
 $(this).val(value[i]);
 $(this).change();
 $(this).siblings('#img_semanticPic').attr('src', value[i]);

 // Se trova l'immagine deve togliere il require all'input standard
 $('#field_filePhoto').removeClass('requirePhoto');
 } else {
 hideDivSemanticFoto('semantic');
 }
 break;

 case 'skill':
 if (value[i] instanceof Array) {
 let contextId = "#" + $(this).parents('.term-search').attr('id');
 value[i].forEach(label => {
 createSkill(label.term, label.term, contextId, $(this).attr('semantic-name'), true);
 });
 }
 break;

 case 'phone':
 let val = value[i];
 if (val instanceof Array) {
 val = value[i][0];
 }
 if (typeof val !== 'string' || !val instanceof String) {
 break;
 }
 val = val.replace(/[^0-9]+/g, "");
 const plus_pos = val.indexOf('+');
 if (plus_pos !== -1) {
 val = '+' + val;
 }
 const iti = window.intlTelInputGlobals.getInstance(this);
 iti.setNumber(val);
 if (iti.checkNumber && iti.checkNumber instanceof Function) {
 iti.checkNumber();
 }
 break;

 default:
 $(this).val(value[i]);
 if ($.isFunction($(this).change())) $(this).change();
 break;

 }

 i++;
 });
 });
 });
 }

