 function fileInputUpload(file, input) {
 let ext_allowed_array = ["application\/pdf","application\/msword","application\/vnd.openxmlformats-officedocument.wordprocessingml.document","application\/vnd.ms-excel","application\/vnd.openxmlformats-officedocument.spreadsheetml.sheet","application\/vnd.ms-powerpoint","application\/vnd.openxmlformats-officedocument.presentationml.presentation","application\/vnd.oasis.opendocument.text","application\/vnd.oasis.opendocument.presentation","application\/vnd.oasis.opendocument.spreadsheet","text\/plain","application\/rtf","image\/jpeg","image\/gif","image\/png"];
 let field_input = $(input).closest('.field-input');

 if(file.size > 5242880) {
 Swal.fire({
 type: 'error',
 title: 'Error',
 html: 'File larger than upload max file size (Max Size: 5 MB)',
 });
 return false;
 }
 if(!ext_allowed_array.includes(file.type)) {
 Swal.fire({
 type: 'error',
 title: 'Error',
 html: "Invalid format",
 });
 return false;
 }

 $(field_input).find('.text-note-input-file').html(' ' + file.name + '');
 $(field_input).find('.trash-remove-file').show();
 }

