document.addEventListener('DOMContentLoaded', () => {
 const form = document.getElementById('jobApplicationForm');
 const feedback = document.getElementById('applicationFeedback');
 const submitBtn = document.getElementById('submitAppBtn');

 if (form) {
 form.addEventListener('submit', async (e) => {
 e.preventDefault();
 // Handle file uploads via FormData
 const formData = new FormData(form);
 submitBtn.disabled = true;
 submitBtn.innerHTML = 'Uploading application...';

 try {
 const response = await fetch("/careers/azure-cloud-solutions-architect/apply/", {
 method: 'POST',
 body: formData,
 headers: {
 'X-Requested-With': 'XMLHttpRequest'
 }
 });

 const data = await response.json();

 if (response.ok && data.success) {
 feedback.style.display = 'block';
 feedback.style.background = '#dcfce7';
 feedback.style.border = '1px solid #86efac';
 feedback.style.color = '#166534';
 feedback.innerHTML = `🎉 Success! ${data.message}`;
 form.reset();
 submitBtn.innerHTML = 'Application Submitted';
 feedback.scrollIntoView({ behavior: 'smooth' });
 } else {
 // If error or validation issue, let fallback or display error
 feedback.style.display = 'block';
 feedback.style.background = '#fee2e2';
 feedback.style.border = '1px solid #fca5a5';
 feedback.style.color = '#991b1b';
 feedback.innerHTML = `Submission issue: Please verify all required fields.`;
 submitBtn.disabled = false;
 submitBtn.innerHTML = 'Submit My Application';
 }
 } catch (err) {
 // Fallback to normal form submit if fetch fails
 console.warn('AJAX submit fallback', err);
 }
 });
 }
});

