 /* === Progress === */
 .form-progress{
 display:grid;
 grid-template-columns:repeat(10,1fr);
 align-items:center;
 list-style:none;
 padding:0;
 margin:0;
 }
 .progress-step{ position:relative; text-align:center; font-size:0; }
 .progress-step::before{
 content:attr(data-step);
 display:block;
 width:36px; height:36px; line-height:36px;
 margin:0 auto;
 border-radius:50%;
 border:2px solid #fff;
 background:transparent;
 color:#fff;
 font-size:14px; font-weight:700;
 box-shadow:0 4px 6px rgba(0,0,0,.2);
 transition:transform .12s ease;
 }
 .progress-step:not(:last-child)::after{
 content:"";
 position:absolute;
 top:18px;
 left:calc(50% + 18px);
 right:calc(-50% + 18px);
 height:2px;
 background:transparent;
 }
 .progress-step.completed::before{ background:#004b2d; color:#fff; border-color:#004b2d; }
 .progress-step.completed:not(:last-child)::after{ background:#fff; }
 .progress-step.active::before{ background:#fff; color:#004b2d; border-color:#fff; }

