 // ====== FETCH VACANCY CONTENT (STEP 2 & 3) Z /vacancies ======
 async function fetchVacancyContent(){
 if (!VACANCY_ID) return;

 // Build URL using the same base path as API_ENDPOINT (which includes /management-portal/)
 let baseUrl = '';
 try {
 const endpointUrl = new URL(API_ENDPOINT);
 // Get the pathname up to /wp-json/ (e.g., /management-portal/wp-json/)
 const pathMatch = endpointUrl.pathname.match(/^(.+?\/wp-json)/);
 if (pathMatch) {
 baseUrl = `${endpointUrl.origin}${pathMatch[1]}`;
 } else {
 // Fallback: use origin + /wp-json
 baseUrl = `${endpointUrl.origin}/wp-json`;
 }
 } catch(e){
 baseUrl = `${window.location.origin}/wp-json`;
 }

 const hasWpCookie = document.cookie.indexOf('wordpress_logged_in_') !== -1;
 const preview = (form.dataset.preview === '1' || hasWpCookie) ? 'jw_preview=1' : '';
 const url = `${baseUrl}/jwcareers/v1/vacancies${preview ? '?' + preview : ''}`;
 const roleBox = document.getElementById('role-entails');
 const soundBox = document.getElementById('does-sound-like-you');

 try {
 const res = await fetch(url, { 
 credentials: 'include',
 mode: 'cors'
 });
 if (!res.ok) {
 console.warn('Vacancies endpoint returned status', res.status, url);
 return;
 }

 const list = await res.json();
 console.log('Vacancies list:', list);

 // Znajdź ofertę po ID
 const vacancy = Array.isArray(list)
 ? list.find(item => parseInt(item.id, 10) === VACANCY_ID)
 : null;

 if (!vacancy) {
 console.warn('Vacancy not found for ID', VACANCY_ID, 'in', list);
 return;
 }

 const status = (vacancy.vacancy_status || '').toString().toLowerCase();

 let roleHTML = '';
 let soundHTML = '';

 // STEP 2 – "role entails" (zauważ spację w kluczu)
 roleHTML =
 vacancy['role entails'] || // dokładnie taki klucz jak w JSON
 vacancy.role_entails || // fallback gdyby kiedyś zmienili
 vacancy.what_you_will_be_doing || // sensowny fallback z API
 '';

 // STEP 3 – "does_this_sound_like_you"
 soundHTML =
 vacancy.does_this_sound_like_you ||
 '';

 if (roleBox && roleHTML) roleBox.innerHTML = roleHTML;
 if (soundBox && soundHTML) soundBox.innerHTML = soundHTML;

 if (!roleHTML && !soundHTML) {
 console.warn('Vacancy found, but no expected text fields (role entails / does_this_sound_like_you). Vacancy:', vacancy);
 } else {
 console.log('Vacancy content injected into steps 2 & 3 from', url, 'for ID', VACANCY_ID);
 }

 } catch(err){
 console.error('Error fetching vacancy content:', err);
 }
 }

 updateFname();
 showStep(currentStep);

 fetchVacancyContent();
 });

