 roleSelect.replaceChildren(new Option('Choose a role…', ''));
 live.forEach((item) => roleSelect.add(new Option(item.title, item.slug)));
 roleSelect.value = live.some((item) => item.slug === chosen) ? chosen : '';
 }
 if (slug) {
 const found = live.find((item) => item.slug === slug);
 showRole(found);
 if (!found) {
 heading.textContent = 'Apply to LEC AI';
 subheading.textContent =
