 (function(){const roleIndex = [];
const APPLY_ENDPOINT = "https://lecai.ai/careers/api/applications";
const LIVE_FEED = "/careers/api/jobs";

 (function () {
 /**
 * Where a submission goes: PUBLIC_APPLY_ENDPOINT, fixed at build time. Empty
 * means the form refuses to send (see the submit handler), never a guessed host.
 */
 const ENDPOINT = APPLY_ENDPOINT;

 const MAX_CV_BYTES = 5 * 1024 * 1024;
 const CV_EXTENSIONS = ['.pdf', '.doc', '.docx'];

 const form = document.getElementById('apply-form');
 if (!form) return;

 const heading = document.getElementById('apply-heading');
 const subheading = document.getElementById('apply-subheading');
 const pickerWrap = document.getElementById('role-picker-wrap');
 const roleSelect = document.getElementById('role');
 const summary = document.getElementById('error-summary');
 const summaryList = document.getElementById('error-list');
 const summaryTitle = document.getElementById('error-title');
 const submitBtn = document.getElementById('submit-btn');
 const btnText = document.getElementById('btn-text');
 const btnSpinner = document.getElementById('btn-spinner');
 const success = document.getElementById('apply-success');
 const successDetail = document.getElementById('success-detail');
 const cvInput = document.getElementById('cv');
 const dropzone = document.getElementById('cv-dropzone');
 const chosen = document.getElementById('cv-chosen');

 // Which role is this? ?role=slug, else let them pick.
 const slug = new URLSearchParams(window.location.search).get('role');
 let role = roleIndex.find((item) => item.slug === slug);
 const showRole = (found) => {
 role = found;
 if (found) {
 heading.textContent = found.title;
 subheading.textContent = found.location;
 if (roleSelect) roleSelect.value = found.slug;
 pickerWrap.hidden = true;
 } else {
 subheading.textContent = 'Tell us which role you have in mind.';
 pickerWrap.hidden = false;
 }
 };
 showRole(role);

 // The live roles, from the same feed the careers page refreshes from. Same
 // origin by default; if it cannot be reached the build-time list stands.
 (async () => {
 if (!LIVE_FEED) return;
 const controller = new AbortController();
 const timer = setTimeout(() => controller.abort(), 8000);
 try {
 const response = await fetch(LIVE_FEED, {
 signal: controller.signal, cache: 'no-store', credentials: 'omit',
 headers: { Accept: 'application/json' },
 });
 if (!response.ok) throw new Error(`feed returned ${response.status}`);
 const payload = await response.json();
 const records = Array.isArray(payload) ? payload : payload && payload.records;
 if (!Array.isArray(records)) throw new Error('feed returned no records array');
 // The same rule as the careers page: Published, with a slug.
 const live = records
 .map((record) => record && record.fields ? record.fields : {})
 .filter((f) => f['Status'] === 'Published' && String(f['Slug'] || '').trim())
 .map((f) => ({
 slug: String(f['Slug']).trim(),
 title: String(f['Title'] || 'Untitled role').trim(),
 location: [String(f['Location'] || '').trim(), String(f['Work Mode'] || '').trim()]
 .filter(Boolean).join(' · '),
 }));
 if (roleSelect) {
 const chosen = roleSelect.value;
 roleSelect.replaceChildren(new Option('Choose a role…', ''));
 live.forEach((item) => roleSelect.add(new Option(item.title, item.slug)));
 roleSelect.value = live.some((item) => item.slug === chosen) ? chosen : '';
 }
 if (slug) {
 const found = live.find((item) => item.slug === slug);
 showRole(found);
 if (!found) {
 heading.textContent = 'Apply to LEC AI';
 subheading.textContent =
 'That role is no longer open. Choose another below, or email talent@lecai.ai.';
 }
 }
 } catch (error) {
 console.info('[careers] live roles unavailable; using the published list.', String(error));
 } finally {
 clearTimeout(timer);
 }
 })();

 // --- Validation -----------------------------------------------------
 const setError = (id, message) => {
 const field = document.getElementById(id);
 const slot = document.querySelector(`[data-error-for="${id}"]`);
 if (slot) slot.textContent = message || '';
 if (field) {
 field.setAttribute('aria-invalid', message ? 'true' : 'false');
 field.classList.toggle('border-[#d70015]', Boolean(message));
 }
 if (id === 'cv' && dropzone) dropzone.classList.toggle('border-[#d70015]', Boolean(message));
 };

 const value = (id) => (document.getElementById(id).value || '').trim();

 const checks = {
 role: () => (pickerWrap.hidden || value('role') ? '' : 'Choose the role you are applying for.'),
 'first-name': () => (value('first-name') ? '' : 'Please give your first name.'),
 'last-name': () => (value('last-name') ? '' : 'Please give your last name.'),
 email: () => {
 const email = value('email');
 if (!email) return 'Please give an email address we can reply to.';
 return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? '' : 'That does not look like an email address.';
 },
 phone: () => {
 const phone = value('phone');
 if (!phone) return 'Please give a phone number.';
 return phone.replace(/[^0-9]/g, '').length >= 7 ? '' : 'That does not look like a phone number.';
 },
 linkedin: () => {
 const url = value('linkedin');
 if (!url) return '';
 try {
 new URL(url);
 return '';
 } catch {
 return 'Include the full address, starting with https://';
 }
 },
 cv: () => {
 const file = cvInput.files && cvInput.files[0];
 if (!file) return 'Please attach your CV.';
 const name = file.name.toLowerCase();
 if (!CV_EXTENSIONS.some((ext) => name.endsWith(ext))) return 'Attach a PDF, DOC or DOCX file.';
 if (file.size > MAX_CV_BYTES) return 'That file is over 5 MB. Please attach a smaller one.';
 return '';
 },
 consent: () =>
 document.getElementById('consent').checked
 ? ''
 : 'Please agree to the Terms of Use and Privacy Policy to apply.',
 };

 Object.keys(checks).forEach((id) => {
 const field = document.getElementById(id);
 if (!field) return;
 field.addEventListener('blur', () => {
 if (field.getAttribute('aria-invalid') === 'true' || value(id)) setError(id, checks[id]());
 });
 field.addEventListener('input', () => {
 if (field.getAttribute('aria-invalid') === 'true') setError(id, checks[id]());
 });
 });

 document.getElementById('consent').addEventListener('change', () => {
 setError('consent', document.getElementById('consent').getAttribute('aria-invalid') === 'true' ? checks.consent() : '');
 });

 // --- CV file --------------------------------------------------------
 const formatSize = (bytes) =>
 bytes {
 const file = cvInput.files && cvInput.files[0];
 if (!file) {
 chosen.hidden = true;
 dropzone.hidden = false;
 return;
 }
 document.getElementById('cv-name').textContent = file.name;
 document.getElementById('cv-size').textContent = formatSize(file.size);
 chosen.hidden = false;
 dropzone.hidden = true;
 setError('cv', checks.cv());
 };

 cvInput.addEventListener('change', showFile);

 document.getElementById('cv-remove').addEventListener('click', () => {
 cvInput.value = '';
 showFile();
 setError('cv', '');
 cvInput.focus();
 });

